function roadPatternIndex(scene,x,y){if(scene.biome!=='mire')return Math.floor(rand(Math.floor(x/128)*971+Math.floor(y/128)*293)*4);let distance=Infinity,index=0;for(const road of scene.roads)for(let i=1;i<road.length;i++){const a=road[i-1],b=road[i],dx=b.x-a.x,dy=b.y-a.y,t=Math.max(0,Math.min(1,((x-a.x)*dx+(y-a.y)*dy)/(dx*dx+dy*dy||1))),d=(x-a.x-dx*t)**2+(y-a.y-dy*t)**2;if(d<distance){distance=d;index=Math.abs(dx)>Math.abs(dy)?0:1;}}return index;}
