  if(kind==='path'){const overWater=scene.water?.some(poly=>insidePolygon(wx+6,wy+6,poly))&&!scene.islands?.some(([cx,cy,rx,ry])=>(wx-cx)**2/rx**2+(wy-cy)**2/ry**2<1);if(overWater){rect(c,x,y,12,12,'#827b60');rect(c,x,y+2,12,1,'#b2a17b');rect(c,x,y+9,12,2,'#49594f');rect(c,x+3,y+4,2,2,'#464d45');continue;}rect(c,x,y,12,12,r>.84?p.sand:p.path);if(r>.7)rect(c,x+2,y+8,3,1,p.stoneDark);if(r>.96){rect(c,x+1,y+2,8,5,p.stone);rect(c,x+1,y+2,8,1,p.stoneLight);}continue;}
