 if(color){const key=`${index}:${color}:${w.toFixed(2)}:${h.toFixed(2)}`;let mask=lootOutlineCache.get(key);if(!mask){mask=artSurface(Math.ceil(w)+8,Math.ceil(h)+8);const cc=mask.getContext('2d');draw(cc,4,4);cc.globalCompositeOperation='source-in';cc.fillStyle=color;cc.fillRect(0,0,mask.logicalWidth,mask.logicalHeight);lootOutlineCache.set(key,mask);}const pulse=reducedMotion?.5:(Math.sin(time*1.65)+1)*.5;c.save();c.globalAlpha=.06+pulse*.035;for(const[dx,dy]of[[-2,0],[2,0],[0,-2],[0,2]])c.drawImage(mask,left-4+dx,top-4+dy,mask.logicalWidth,mask.logicalHeight);c.globalAlpha=.23+pulse*.11;for(const[dx,dy]of[[-.8,0],[.8,0],[0,-.8],[0,.8]])c.drawImage(mask,left-4+dx,top-4+dy,mask.logicalWidth,mask.logicalHeight);c.restore();}
