 for(const shore of shores){poly(c,shore.points,shore.col);c.save();c.beginPath();shore.points.forEach(([xx,yy],i)=>i?c.lineTo(xx,yy):c.moveTo(xx,yy));c.closePath();c.clip();for(let i=0;i<48;i++){let xx=i*23+rand(i*13)*8,yy=78+rand(i*19)*76;rect(c,xx,yy,3+rand(i*73)*8,72,'#648b83');if(i%3===0)rect(c,xx-6,yy+22,19,2,'#80a095');}c.restore();}
 rect(c,0,143,960,110,p.sea);if(groundAtlas&&biome==='coast'){c.fillStyle=artPattern(c,groundAtlas[5]);c.fillRect(0,143,960,110);}if(!(groundAtlas&&biome==='coast')){poly(c,[[0,166],[99,167],[156,144],[206,146],[238,157],[330,159],[372,181],[0,181]],'#406f70');poly(c,[[576,171],[619,151],[657,151],[689,141],[751,142],[789,160],[895,164],[960,181],[576,181]],'#406f70');for(let i=0;i<6;i++){let xx=630+i*29;rect(c,xx,136-i%2*16,12,25+i%2*16,'#537c76');rect(c,xx-2,134-i%2*16,17,3,'#7d9b8b');}
}
 // Small reused ruins sit on real textured sea stacks, washed toward the horizon palette.
 if(environmentAtlas){c.save();c.globalAlpha=.56;atlasProp(c,'cliff',246,203,130,108);atlasProp(c,'cliff',654,206,181,155);atlasProp(c,'arch',656,129,46,60);atlasProp(c,'cypress',207,147,44,67);c.restore();}
 for(let i=0;i<54;i++){const x=rand(i*37)*960,y=164+rand(i*77)*78;rect(c,x+Math.sin(time*.4+i)*6,y,10+rand(i+8)*36,1,i%7?p.sea2:p.foam);}
 poly(c,[[0,239],[110,219],[170,221],[267,233],[335,238],[448,229],[539,229],[664,249],[751,253],[842,243],[960,229],[960,540],[0,540]],p.stoneDark);poly(c,[[0,233],[110,213],[170,215],[267,226],[335,231],[448,220],[539,223],[664,242],[751,247],[842,236],[960,220],[960,540],[0,540]],p.moss);
 if(groundAtlas&&biome==='coast')texturedPoly(c,[[0,233],[110,213],[170,215],[267,226],[335,231],[448,220],[539,223],[664,242],[751,247],[842,236],[960,220],[960,540],[0,540]],0);
 // An eroded limestone terrace gives combat a human history and a grounded contact plane.
 poly(c,[[52,283],[174,258],[357,267],[411,256],[542,274],[681,265],[828,293],[847,333],[718,361],[541,345],[452,363],[261,337],[153,345],[70,325]],'#7d8d70');
