// Repaint only scenery whose foot is nearer than an actor: canopy and masonry occlude correctly.
export function drawForeground(c,scene,camera,time,state,actors=[]){selectBiome(scene.biome);const p=PALETTES[scene.biome]||P;c.save();c.translate(-Math.round(camera.x||0),-Math.round(camera.y||0));for(const o of scene.objects){if(!['tree','town','house','cave','ruin','landmark'].includes(o.type))continue;const size=o.size||1,half=o.type==='tree'?72*size:o.type==='landmark'?140*size:o.type==='town'?125:90,height=o.type==='tree'?172*size:o.type==='landmark'?290*size:o.type==='town'?265:180;const occluded=actors.some(a=>a.y<o.y+5&&a.y>o.y-height&&Math.abs(a.x-o.x)<half);if(!occluded)continue;c.globalAlpha=o.type==='tree'?.42:.42;drawProp(c,o,p,time,state);}c.restore();}

export function artMetrics(){
 const bytesOf=images=>[...images].reduce((n,im)=>n+(im?.width||0)*(im?.height||0)*4,0);
 const sources=new Set([...environmentAtlases.values(),...enemySheets.values(),...heroSheets.values(),...heroWalkSheets.values(),...buildingAtlases.values(),interiorAtlas,domesticAtlas,worldPropAtlas,civilianAtlas,kaidaSheet,kaidaWalkSheet].map(a=>a?.image).filter(Boolean));
 const frames=new Set([...enemySheets.values(),...heroSheets.values()].flatMap(a=>a.frames||[]).map(f=>f.image).filter(Boolean));
 const tiles=new Set([...groundAtlases.values()].flatMap(a=>a.tiles.concat(a.roads.slice(1))).concat(interiorGroundAtlas||[],interiorWallAtlas||[]));
 return{groundChunks:groundCache.size,groundBytes:bytesOf(groundCache.values()),groundLimitBytes:40*(384*RENDER_SCALE)**2*4,propCacheEntries:propCache.size,propBytes:bytesOf(propCache.values()),groundAtlasBytes:bytesOf(tiles),retainedSourceBytes:bytesOf(sources),retainedSourceCount:sources.size,frameCacheBytes:bytesOf(frames)+bytesOf((worldPropAtlas?.frames||[]).map(f=>f.image).filter(Boolean)),worldPropBytes:bytesOf(lootOutlineCache.values()),worldProps:!!worldPropAtlas,environmentAtlas:!!environmentAtlas,environmentBiomes:[...environmentAtlases.keys()],groundBiomes:[...groundAtlases.keys()],buildingGroups:[...buildingAtlases.keys()],heroSheets:[...heroSheets.keys()],enemySheets:[...enemySheets.keys()]};
}
// Actor geometry shares the exact crops and anchors used by draw calls.
export function actorBounds(id,{pose='idle',scale=1,side='enemy',facing}={}){let frame=null,factor=.23;
 if(heroWalkSheets.get(id)?.frames.length&&pose==='move'){const sheet=heroWalkSheets.get(id),dir=facing==='up'?2:facing==='down'?1:0;frame=sheet.frames[dir*4];factor=sheet.pixelScale;}
 else if(heroSheets.get(id)?.frames.length){const sheet=heroSheets.get(id);frame=sheet.frames[sheet.poseIndex[pose]??0];factor=sheet.pixelScale;}
 else if(id==='kaida'&&kaidaWalkSheet&&pose==='move')frame=kaidaWalkSheet.frames[0];
 else if(id==='kaida'&&kaidaSheet?.frames){const index={idle:0,move:1,anticipate:3,attack:4,cast:5,heal:5,hurt:6,guard:7,down:8,victory:9}[pose]??0;frame=kaidaSheet.frames[index];}
 else if(enemySheets.get(id)?.frames){const index=enemySheets.get(id).poseIndex?.[pose]??({idle:0,anticipate:1,attack:2,hurt:3,down:4,guard:5,cast:1}[pose]??0);frame=enemySheets.get(id).frames[index];factor=enemySheets.get(id).pixelScale||.23;}
 let bounds=frame?{left:-frame.anchorX*factor,top:-frame.anchorY*factor,right:(frame.w-frame.anchorX)*factor,bottom:(frame.h-frame.anchorY)*factor}:side==='hero'?{left:-28,top:-79,right:pose==='attack'?65:35,bottom:4}:{left:-68,top:-62,right:52,bottom:6};
 if((side==='hero'&&facing==='left')||(side==='enemy'&&facing==='right'))bounds={...bounds,left:-bounds.right,right:-bounds.left};return Object.fromEntries(Object.entries(bounds).map(([k,v])=>[k,v*scale]));}
